from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    # LCG mode
    if 'SEED' in inputs:
        s = int(inputs['SEED'])
        a = int(inputs['A'])
        b = int(inputs['B'])
        m = int(inputs['M'])
        k = int(inputs['K'])
        for _ in range(k):
            s = (a * s + b) % m
        return s
    # GCD mode with provided values via V0..Vn
    elif 'V0' in inputs:
        values = []
        i = 0
        while f'V{i}' in inputs:
            values.append(int(inputs[f'V{i}']))
            i += 1
        return reduce(gcd, values)
    else:
        return 0

