def solve(inputs: dict) -> float:
    # Luhn procedure
    digits = [int(d) for d in str(79034020796213133486860787495636841586)]
    # From the right, double every second digit
    result = []
    for i, d in enumerate(reversed(digits)):
        if i % 2 == 1:  # every second digit from right (0-indexed, so positions 1,3,5,...)
            d = d * 2
            if d > 9:
                d -= 9
        result.append(d)
    return sum(result)
